/**
 * What changed in the engine, newest last. session_manage shows the entries a
 * database has not seen yet at initialize / get_context, so a GM learns about
 * a new parameter the session it arrives (the outcome parameter went unused
 * for a whole fight because nothing announced it).
 */
export interface ChangelogEntry {
    id: string;       // sortable: YYYY-MM-DD-NN
    title: string;
    detail: string;
}

export const CHANGELOG: ChangelogEntry[] = [
    { id: '2026-09-24-01', title: 'Post a result you rolled at the table', detail: "combat_action attack {outcome: 'hit' | 'crit' | 'miss', damage}: no engine d20, a posted number is never doubled, a crit doubles dice only. Never fake it with a huge attackBonus." },
    { id: '2026-09-24-02', title: 'Fresh dice for every roll', detail: 'Unseeded rolls never share a seed (the batch repeats are gone). Never pass seed unless you want an exact replay.' },
    { id: '2026-09-24-03', title: 'HP corrections and live conditions', detail: 'combat_manage adjust_hp {value | delta, reason} corrects HP with a logged reason; add_condition / remove_condition work mid-fight.' },
    { id: '2026-09-24-04', title: 'Table rules', detail: "table_rules import {worldId, preset: 'day-366'}: bands, CONSEQUENCE DUE on peers, calledStrike, preparedAsset, regeneration, milestone XP, tiny status, principles at boot." },
    { id: '2026-09-24-05', title: 'Small replies and in-place condition edits', detail: "output_mode: 'summary' on any call returns small fields only; character_manage update {editConditions: [{match, replace: {find, with}}]} edits one condition without resending it." },
    { id: '2026-09-24-06', title: 'Parts, units and intent', detail: "set_part (crippled, dead, latched, breached) with withPart / atPart on attacks; unit tokens with combat_action volley and cleave; set_intent (clears at turn end) and readied actions (stay until trigger_readied)." },
    { id: '2026-09-24-07', title: 'Safe retries with opId', detail: "Pass opId on any write (e.g. opId: 'r12-orla-melta'). A retry with the same opId replays the first reply and applies nothing; after a timeout, session_manage op_status {forOpId} says whether it landed. The same opId with other arguments is refused." },
    { id: '2026-09-24-08', title: 'Every call applies fully or not at all', detail: 'A call that fails or refuses partway leaves no writes behind. batch_manage execute_sequence {atomic: true, steps} makes a whole turn (attack, condition, advance) land together or not at all.' },
    { id: '2026-09-24-09', title: 'Every roll is logged and replayable', detail: "Combat dice, math_manage rolls and checks go to a roll log with who they were for, why, the dice and a replay key. math_manage roll takes forId and purpose. Look them up with session_manage rolls {forId | encounterId | forOpId}." },
    { id: '2026-09-24-10', title: 'Who owns each number', detail: 'The sheet owns HP; a live token reads it before and writes it after every combat action. Conditions, parts, intent and unit state belong to the token unless mirrored. character_manage get lists liveEncounters with the token side. Full table: docs/ownership.md.' },
    { id: '2026-09-24-11', title: 'Precedent ledger', detail: "precedent_manage record {worldId, kind: 'ruling' | 'invention', statement, scope} every ruling and invention; search before ruling again; supersede keeps the old one." },
    { id: '2026-09-24-12', title: 'Knowledge ledger', detail: "knowledge_manage: record a fact and who knows it; learn {knowerId, how: witnessed | told | position | deduced | read | rumour, fromId}; can_know before an NPC states a fact. Telling needs a teller who knows; effectOnKnower applies to each knower." },
    { id: '2026-09-24-13', title: 'Features as data', detail: "improvisation_manage feature_from_condition {characterId, match, triggers?, cost?, mechanics?} turns a prose condition into a structured feature (the prose kept alongside); edit_effect {effectId, descriptionReplace | cost | mechanics | triggers} edits one clause. apply_effect takes cost." },
    { id: '2026-09-24-14', title: 'Session boot packet', detail: "session_manage boot {worldId}: what's new, table rules, character digests (features marked engine-applied or reminder, with cost), clocks and debts due, open threads, live telegraphs, last journal entries, recent precedents. One call before play." },
    { id: '2026-09-24-15', title: 'Pick the fields you need', detail: "Add fields: ['hp', 'conditions'] to any call to get only those fields back (plus success, error, actionType and message)." },
    { id: '2026-09-24-16', title: 'Setup fixes', detail: "Decimal money no longer breaks character get and list. character_manage get returns worldId. The core pool matches in any case. Batch steps with array params (precedent tags, knowledge knowers) are refused; make those calls directly." },
    { id: '2026-09-24-17', title: 'World lexicon', detail: "table_rules kind 'lexicon' {currency, badge, questFailLine} names the engine's fixed labels for a world. The day-366 preset sets Thrones and a +++ header. Change it with table_rules define {kind: 'lexicon', name: 'lexicon', spec}." },
    { id: '2026-09-24-18', title: 'Consequences from above', detail: "peer_consequence direction: 'both' (set by the day-366 preset) flags a higher band's significant hit on a lower one as CONSEQUENCE DUE (from above). A hit that kills, or a hit on a unit, never flags. Track souls as a pool (adjust_pool {pool: 'souls'}) and debts of souls in ledger_manage with currency: 'souls'." },
    { id: '2026-09-24-19', title: 'Pinned conditions and source edits', detail: "editConditions takes replaceSource {find, with} for text in a condition's source, and pinned: true. The tiny status block and the boot digest show pinned conditions first, then the newest, so old grants no longer crowd out the fight. Out of combat, regeneration ticks when time passes through world_manage update {environment}." },
    { id: '2026-09-24-20', title: 'Honest dice with two server processes', detail: "Claude Desktop runs two engine processes on one database. Each kept its own copy of a live encounter, so a stale copy rolled the other's dice again and saved over its writes. Every call now takes the write lock and reads the encounter fresh; dice never repeat across processes." },
    { id: '2026-09-24-21', title: 'No false ghosts', detail: "Every call reads the encounter from the database now, so a live fight is never mistaken for a ghost. combat_manage end closes it properly (and a second end writes nothing and pays no XP twice); death_save and lair_action work on a live fight; list shows active encounters as running; list buryGhosts closes active rows only with confirmBury: true." },
    { id: '2026-09-24-22', title: 'Statlines stay on the token', detail: "combat_manage create participants and add_participant take size, reach, movementSpeed, attackDamageType, attacksPerAction, attacks [{name, attackBonus, damage, damageType?, part?}], abilities [{name, recharge?}], legendaryActions, legendaryResistances, autoLegendaryResistance, hasLairActions and cr; none are stripped at create any more, and a lair owner added mid-fight brings its LAIR slot. A spent legendary resistance is not refilled by a new fight. Parts take holds, ac, hp, maxHp and breakAt, and set_part and called strikes now merge into the part instead of replacing it. A name that matches a preset ('Goblin 2') keeps its name." },
    { id: '2026-09-24-23', title: 'Statlines on the sheet', detail: "character_manage create and update take size, reach, attacksPerAction, attacks, abilities, cr, autoLegendaryResistance, legendaryActions, legendaryResistances, legendaryResistancesRemaining and hasLairActions. Set a recurring monster's statline once on its sheet; combat_manage create and add_participant with its id bring it onto the token, and anything you pass there still wins." },
    { id: '2026-09-24-24', title: 'Saves in combat read the sheet', detail: "Spell saves, lair saves and concentration saves now add the ability modifier and save proficiency from the character sheet (a token without one uses its own ability scores), roll on the encounter's seeded dice and show up in session_manage rolls. Spell saves were rolling +0 before. A creature with autoLegendaryResistance spends one on a failed save and succeeds; otherwise the result says how many it has left." },
    { id: '2026-09-24-25', title: 'Conditions play themselves', detail: "The 5e standard conditions now apply their own advantage and disadvantage on attacks: a prone, poisoned, blinded, restrained or frightened attacker rolls at disadvantage; a blinded, restrained, stunned, paralysed or petrified target is hit at advantage; prone is advantage within 5 ft and disadvantage beyond; invisible and hidden cut both ways; a rolled hit on a paralysed or unconscious target within 5 ft is a crit (a posted outcome is only noted). Homebrew tags like cursed or marked never fire. Pass ranged: true for a shot from range, or ignoreConditions: true for a raw roll; a hand-passed disadvantage still works. Grappled, restrained, stunned, paralysed, petrified and unconscious creatures can't move, even mid-turn; prone no longer stops movement. Exhaustion takes a level ({name: 'exhaustion', level: 3}): 2 halves speed, 3 adds disadvantage on attacks, 5 stops movement. 'paralysed' and 'exhaustion' are understood. remove_condition takes condition (a name, or the object add_condition returned); add_condition takes a top-level name." },
    { id: '2026-09-24-26', title: 'Attacks by name, strikes at any part', detail: "combat_action attack takes using: '<attack name>' (or weapon): the named attack on the token or sheet fills the bonus, damage, damage type and the part that swings, and anything you pass still wins. With nothing named and no bonus, the attack marked default (or the only one) replaces the STR/DEX guess. calledStrike takes any part the target has ('jaw', 'collar chain'): the part keeps its kind and its hold, and a name the target doesn't have is refused with its parts listed. A crippled arm only puts an unnamed attack at disadvantage when no intact arm is declared; name the weapon and the arm that holds it (set_part holds: ['whip']) decides." },
    { id: '2026-09-24-27', title: 'Armoured parts', detail: "set_part takes ac, hp (maxHp) and breakAt: combat_manage set_part {part: 'collar chain', kind: 'other', state: 'intact', ac: 22, breakAt: 30}. An attack aimed at it (atPart) rolls against the part's AC when you give no dc. A hit on a part with hp or breakAt lands on the part, not the body: the body takes 0, so no HP write, concentration check or CONSEQUENCE DUE. A hit of breakAt or more, or hp run down to 0, severs the part (state dead, note 'severed') and releases its latch and anything latched onto it. The result's partHit {name, damage, hpBefore, hpAfter, broken, state} says what happened; the state render shows each part's AC, HP and break threshold." },
    { id: '2026-09-24-28', title: 'Multiattack and legendary actions', detail: "A creature with attacksPerAction: 2 makes two combat_action attack calls in one Attack action (each can name its own weapon); the result carries multiattack {made, of} and prints 'attack 2/2', and a third is refused. A Dash or spell after the first swing is still refused. Presets whose traits say Multiattack (troll, owlbear, bears, harpy, bandit captain) carry it. Off its turn, a boss attacks with legendaryCost: N (spends legendary actions, not its action, no off-turn warning); any other legendary action is combat_manage legendary_action {participantId, cost?, description}. combat_manage legendary_resistance {participantId, reason} spends one and writes the count to the sheet. The 'legendary' alias now means legendary_action (lair_action keeps 'lair'). An attack with reaction: true spends the reaction. The state view shows LA 2/3 · LR 1/3 · attacks 1/2." },
    { id: '2026-09-24-29', title: 'Size fills squares and sets reach', detail: "A token's size now counts on the grid: a large creature fills 2x2 squares from its position, huge 3x3, gargantuan 4x4, and every square it fills blocks movement (a large mover needs its whole footprint clear at the destination). Opportunity attacks measure from the edge of each footprint and use reach: huge and gargantuan reach 10 ft, and a token's reach (or an attack's reachFt) wins. A large creature now threatens every square next to its footprint. spawn_quick_enemy tokens carry the preset's size, speed, damage type and CR." },
    { id: '2026-09-24-30', title: 'Grapple in one call', detail: "combat_action grapple {encounterId, actorId, targetId, move} now rolls on the fight's logged dice and spends one attack of the Attack action (break spends the action); a token without a character sheet can grapple. The lower band or smaller size rolls at disadvantage by itself, once, with the reason printed. A target more than one size larger is refused, and throw or slam of anything larger. control: true pins instead of hurting: a win leaves the target Grappled and Restrained and rolls no surface damage. move: 'execute' finishes a foe this actor pinned (restrained, or grappled and prone) of a lower band as a posted crit of its HP, or of the damage you pass. move: 'break' clears only the holds from the holder named in targetId, and the escaper uses the better of Athletics and Acrobatics. Holds on sheets are now sourced 'grapple: <actorId>', like the tokens." },
    { id: '2026-09-24-31', title: 'Saving throws in one call', detail: "math_manage roll_saving_throw {characterId, ability, dc} is the save verb: it reads the sheet (ability modifier, save proficiency, autoApply traits) and takes the long name in any case ('Wisdom'). advantageSources / disadvantageSources: ['VAUREK'] each name one of the character's conditions (by name or source) or active effects; the roll gets advantage and the log says why ('wis save (adv: VAUREK)'). A name that matches nothing, or more than one thing, is refused and grants nothing. Effects with advantage_on / disadvantage_on apply by themselves when autoApply is set (scoped by save or skill), or when you name them in declaredEffects. A failed save by a creature with legendary resistances left reports legendaryResistanceAvailable; spend one with combat_manage legendary_resistance. Skill and ability checks take the same fields." },
    { id: '2026-09-24-32', title: 'Reactions on the move', detail: "A move is checked first (blocked, no path, not enough movement) and only then provokes, so a refused move spends no reaction. Opportunity attacks now follow the whole path: skirting an enemy's reach provokes where the path leaves it, and a mover who drops stops on that square. Stunned, paralysed, unconscious and other creatures that can't react make none. An opportunity attack rolls like any attack: a prone mover within 5 ft is hit with advantage, Dodge gives disadvantage, a hit on a paralysed mover is a crit, and a unit loses at most one model. NPCs swing by themselves; a PC's opportunity attack is offered in opportunityAttacksAvailable with the exact combat_action attack {reaction: true} call. Each one is data in the move result (opportunityAttacks, with the step and square). combat_action ready now writes the readied action on the token and spends the action (an action already spent warns). A readied action with on: 'enters_reach' | 'leaves_reach', watch (an id, name, 'enemy' or 'any') and attack {using?, attackBonus?, damage?} fires itself as a reaction when a move sets it off, for NPCs and PCs alike; without attack it is flagged in readiedTriggered. trigger_readied spends the reaction (refused when it is spent or the creature can't react) and rolls the stored attack in the same call (targetId)." },
    { id: '2026-09-24-33', title: 'A bestiary per world', detail: "Save a statblock once with table_rules define {worldId, kind: 'creature', name: 'Chaos Spawn', spec: {hp, ac, stats?, attacks?, attacksPerAction?, abilities?, size?, cr?, band?, regeneration?, parts?, resistances?, traits?}}, or capture one from a live token (fromToken {encounterId, participantId}) or a sheet (fromCharacterId), with spec merged on top. Every fight after, combat_manage spawn_quick_enemy {creature: 'Chaos Spawn', count, worldId} or add_participant {encounterId, creature, count} builds the tokens with all of it (parts start intact, abilities ready); anything passed to add_participant wins. A world entry beats a built-in preset of the same name, and spawn_quick_enemy stamps the new encounter to the world. Session boot shows 'Bestiary: N creatures' and never lists them as enforced rules. A rule name is unique per world across kinds: define refuses to change an existing rule's kind." },
    { id: '2026-09-24-34', title: 'Recharge abilities, a proper lair, and an XP budget', detail: "A spent ability with a recharge number (abilities: [{name: 'Fire Breath', recharge: 5}]) rolls a logged d6 at the start of its creature's turn; the advance output says whether it came back. combat_manage use_ability {encounterId, participantId, ability, targetIds?, damage?: number | '12d6', damageType?, savingThrow?: {ability, dc}, halfDamageOnSave?} spends the action, marks the ability spent, rolls the damage once and a save per target on the fight's dice; a spent ability is refused. The state view lists abilities and marks the spent ones. Lair actions: a creature that rolled 20 now acts before the lair (the lair loses ties); the LAIR slot shows in the initiative list with 'LAIR ACTION PENDING'; a second lair_action in one round is refused; the lair's turn is skipped once its owner is dead; lair damage takes dice ('2d10'). combat_manage budget {partyLevels | partyId, creatures: [{creature | cr | xp, count?}] | encounterId} rates a fight by the 5e XP budget (trivial to deadly) without changing anything, and the threat line on create and spawn_quick_enemy adds the adjusted XP and difficulty when the hostiles have a CR and the allies a level." },
    { id: '2026-09-24-35', title: 'One world clock', detail: "world_manage advance {worldId, minutes | hours | days} moves the stored clock forward (midnight handled), heals regenerators like update does, and returns dueNow {scheduled, debts}: how many clocks and debts the new time has reached (fire them with process_scheduled and process_due; nothing fires by itself). Without a day passed, character_manage process_scheduled, schedule_change firesInHours and ledger_manage process_due use the world clock, and the reply says clockSource: 'world' (a day you pass still wins, clockSource: 'param'). Knowledge roads, precedents and narrative append sections are stamped with the world day when you give none. The boot packet marks a debt DUE once the world day reaches it and shows the time; the status block shows the clock and weather for the character's own world even when the database holds several; get_context returns day and time." },
    { id: '2026-09-24-36', title: 'Counters you can see', detail: "character_manage adjust_pool takes label (\"An'ggrath's calls\"), note, show and linkItem. show: true lists the counter in the boot digest and on the status block (tiny and full) as 'An'ggrath's calls 2/3'. linkItem (an item template or instance id the character owns) ties a token item to the pool: the pool is the truth and the item's charges follow it on every write, scheduled refills included, and inventory_manage adjust_charges on that item is refused with the adjust_pool call to use. Setting label, note or show alone changes nothing else. The history that reason and witnesses write is now kept (it was dropped on the next read), and the pool line prints current/max." },
    { id: '2026-09-24-37', title: 'Condition names without the sheet', detail: "fields take dotted paths: fields: ['conditions.name', 'conditions.pinned'] returns each condition with just those keys (the same works for any list or object in a reply, e.g. 'tokens.name'). character_manage get returns conditionNames, so fields: ['conditionNames'] is the whole index in a few bytes. An editConditions match that hits several conditions now names them in the refusal." },
    { id: '2026-09-24-38', title: 'Long threads stay light', detail: "narrative_manage add, update and append return size {chars, softCap: 8000, over} and, past 8000 characters, a warning naming the archive call; nothing is refused. narrative_manage archive {noteId, keepLast?: 2, preview?} moves the older appended sections to a new note with status 'archived' (same world, type, tags and visibility), leaves a marker line naming it, and keeps the head and the newest sections; with too few sections it refuses and writes nothing. The boot packet shows a grown thread as its first line plus its latest section (marked long past the cap) instead of its oldest 160 characters. fields and output_mode: 'summary' now work on narrative_manage and other tools that reply with plain JSON. append_section is an alias of append." },
    { id: '2026-09-24-39', title: 'The house status block from data', detail: "The status_block rule takes conditionLayout: 'line' (one row, 'COND A · B'; conditionLabel renames COND), showMore: false (no '+N more'), showLocation / showObjective: false (no AT / OBJ rows) and footer: a line under the frame built from segments joined by ' · '. Segments: 'scene.place' (the character's latest scene's place), 'scene.<key>' (that scene's engineState value, as 'Key: value'), 'knows:<key prefix>' (facts in knowledge_manage whose key starts with the prefix: 'Vaurek (2 of 4)', or just 'Vaurek' when all are known; 'knows:<prefix>|Label' names it), 'location', 'objective'; any other text prints as written, and a segment with nothing behind it is left out. Unset, the block reads as before." },
    { id: '2026-09-24-40', title: 'Combat review fixes', detail: "The rest of a multiattack can't be finished on another creature's turn. A legendary resistance a creature spends by itself (autoLegendaryResistance) is written to its sheet, so the next fight doesn't give it back. spawn_manage encounters keep each token's AC, attack and multiattack after the engine reloads. Exhaustion 3 or more puts saves in combat at disadvantage too, and the save says why." },
    { id: '2026-09-24-41', title: 'Regeneration and CR in the state view', detail: "combat_manage get (and every state reply) now lists a token's regeneration and CR in its participant entry, so a creature spawned from the bestiary shows what it heals each round without reading the sheet." },
    { id: '2026-09-26-01', title: 'Advantage sources prefer the exact name', detail: "roll_saving_throw advantageSources / disadvantageSources match exactly first, then by the start of a name, then anywhere in it: 'Blessed' names the effect Blessed even when 'Blessed by Nurgle' is also on the sheet. Two hits on the deciding tier are still refused, and the warning says which tier (\"matches 2 conditions or effects by prefix\")." },
    { id: '2026-09-26-02', title: 'Spells roll on the logged dice and apply their conditions', detail: "cast_spell rolls its attack d20, damage and healing on the encounter's seeded stream, so every die is in session_manage rolls (the attack as 'spell attack', with its target). The spell attack reads the same conditions, Dodge and Help as a weapon attack (a prone target at range is disadvantage; a paralysed one within 5 ft is crit on a hit). Debuff spells now apply their conditions: Hold Person paralyses each target that fails its WIS save, Hex marks its target with no save; the result lists them in conditionsApplied. Healing adds the caster's own casting stat (CHA for a bard) instead of always WIS, and a sheet's spellAttackBonus of 0 is used as 0. scroll_manage Arcana checks are seeded and logged." },
    { id: '2026-09-26-03', title: 'Random tables', detail: "table_rules has a roll_table kind for any table a world keeps (the Eye of the Gods, miscasts, omens, weather): table_rules define {worldId, kind: 'roll_table', name, spec: {entries: [{weight, text} | {min, max, text}], dice?, modifierPool?, poolDivisor?}}. Weights read as ranges from 1 (weights 2, 1, 1 are 1-2, 3, 4 on a 1d4). table_rules roll {worldId, name, characterId?, modifier?} rolls it on seeded, logged dice: the modifier, plus the character's modifierPool ÷ poolDivisor, shifts the total, clamped to the table. An entry's chain rolls the next table (5 deep). Session boot lists tables, like the bestiary, as data (Data: roll_table 2), not as enforced rules." },
    { id: '2026-09-26-04', title: 'Corpse loot on logged dice', detail: "corpse_manage generate_loot rolls on a seed and logs the dice (session_manage rolls); the result carries seed and rollId, and passing the seed back replays the same loot. loot_table_roll, which the description promised, is now an alias of generate_loot." },
    { id: '2026-09-26-05', title: 'Favour families', detail: "table_rules kind pool_family {pools, max?, floor?, jealousy: {gainer: {rival: fraction}}, offering_values} groups rival pools (the four gods). character_manage adjust_pool {pool, delta, family} moves the pool inside its family: a gain makes each jealous rival lose round(gain × fraction), the family's floor (which may be negative) and max clamp, every moved pool keeps a history line, and the reply lists rivals[]. value with family, or a pool outside the family, is refused and writes nothing." },
    { id: '2026-09-26-06', title: 'Forms', detail: "character_manage set_form {characterId, form, hpMode?} gives a character the shape of any creature in the world's bestiary or the presets (Daemon Prince, Chaos Spawn): stats, HP, AC, size, reach, attacks, abilities, resistances, regeneration, band, parts and legendary counts. The fields the form names replace the sheet's (stats merge); the rest stay. hpMode keep_fraction (default) keeps the share of HP left, full heals to the new maximum, keep keeps the number. The sheet keeps its own values in form.base, so form: 'base' puts the form down, even after several forms. Tokens in active encounters change with it." },
    { id: '2026-09-26-07', title: 'Table results apply themselves', detail: "A roll_table entry can carry apply: {gift: {name, description?, category?, powerLevel?, mechanics?}, condition: {name, duration?, source?, pinned?}, writes: [the schedule_change ops], form: '<creature>' | 'base', hpMode?, terminal: 'kill', corpse?}. table_rules roll {worldId, name, characterId} applies the entry it lands on to the character, in order: the gift as an effect (the same gift again refreshes it, and says so), the condition and writes (pool history names the table), the form, then death, which stops the chain. Chained entries apply too. apply: false previews and writes nothing; without characterId only the text is rolled. The reply lists applied[]." },
    { id: '2026-09-26-08', title: 'Offerings', detail: "character_manage offer {characterId, family, pool, offering: 'item' | 'kill' | 'deed'} gives an offering to one god of a pool_family. An item (itemId, quantity) leaves the inventory, a kill (victimId) dies with a corpse, a deed (deed) is named. Its value is the value you pass, or the family's offering_values for the item name, 'kill' or the deed in any case (times quantity for items); with neither, or an item not carried, nothing is written. Favour moves through the family, so rivals grow jealous, with 'offering: …' in the pool history. answerTable rolls the god's answer with that pool as its modifier and applies it (apply: false previews)." },
    { id: '2026-09-26-09', title: 'Congregations', detail: "congregation_manage is a new tool for cults: create {worldId, name, god, founderId, size, zeal? (0-10, default 5), family?, location?, weeklyYield?}. Every in-fiction week a congregation gives its founder's god pool weeklyYield, or max(1, round(size × zeal / 100)), through the god's pool_family (so rivals grow jealous). A week untended for more than 7 days costs 1 zeal (tend resets it); at zeal 0 the flock shrinks by a tenth, and at 0 souls it disperses. strike {losses?, zealDelta?} and purge change it by hand. process_weekly {worldId} catches up every whole week from the world clock; world_manage advance reports dueNow.congregations when any are due." },
    { id: '2026-09-26-10', title: 'Linked rooms read again', detail: "spatial_manage link wrote its exitType ('door', 'passage') as the exit's type, which the room reader refused, so a linked room failed on look, get_exits and move. Link now writes type OPEN (LOCKED for a 'locked …' exitType, HIDDEN for 'hidden …' or 'secret …') and keeps the text as the exit's kind; exits already written the old way read as OPEN with their text in kind." },
    { id: '2026-09-26-11', title: 'Gates', detail: "spatial_manage gate_create {name, fromRoomId, toRoomId, direction, travelHours?, toll?: {gold?, silver?, copper?}, holder?, status?: 'open' | 'closed', bidirectional?, worldId?} joins rooms in any networks (realmgates, toll bridges). Its exits have kind 'gate' and its gateId; a closed gate's exits are LOCKED. gate_list {worldId?, roomId?}; set_gate {gateId, status?, holder?, toll?, travelHours?}. traverse {gateId, characterId, advanceClock?} moves a character at either end (the far end only when bidirectional) through an open gate, taking the toll from their purse (refused if short, nothing written); advanceClock: true moves the world clock by travelHours and returns dueNow. The holder is a label only." },
    { id: '2026-09-26-12', title: 'The warband', detail: "party_manage add_member and update_member take loyalty (0-10; unset reads 5), wage (gold), payMode ('wage' | 'share' | 'none'; default wage when a wage is set, else none) and unitModels. muster {partyId} lists the roster with loyalty, pay and models, and the wages due. pay {partyId, payerId?, amount?} pays from the payer's purse (default the leader): wages first, then, with amount, what is left split by sharePercentage; each member paid gains 1 loyalty, each left unpaid loses 1. after_battle {partyId, victory, casualties?: [{characterId, models?, dead?}], recruits?: [{characterId, role?, loyalty?, wage?, payMode?, unitModels?}]} takes lost models off units, kills the dead (and a unit with no models left) with a corpse and strikes them off, moves every survivor's loyalty 1 up for a victory or down for a defeat, and adds the recruits. A casualty not in the party, or a recruit who is missing or already in it, is refused and nothing is written." },
    { id: '2026-09-26-13', title: 'World skills, species, classes and backgrounds', detail: "table_rules kinds skill {ability}, species {size?, speed?, abilityBonuses?, languages, traits, hpPerLevel?}, char_class {hitDie, saves, skills, armor?, weapons?, casting?: {as}} and background {skills, languages, tools, gold?} are a world's own character options. character_manage create reads the world's entry first (any case, spaces or underscores) and the SRD second: the class's hit die, saves and skills, the species' bonuses, languages, size and HP per level, the background's skills, languages, tools and gold. level_up and short rests use the world hit die. roll_skill_check and improvisation stunt read a world skill's ability; a stunt takes any skill name, and one that is neither SRD nor a world skill needs ability ('dex'). options {worldId} lists the world's entries under world. A class with casting: {as: 'wizard'} gets a wizard's slots at create, level up and rest, and casts SRD spells as a wizard; its sheet keeps its own class." },
    { id: '2026-09-26-14', title: 'Levels past 20 and world progression', detail: "A caster above level 20 cast no levelled spells and a warlock above 20 broke its rests: spell levels and slots now read as level 20 past it. table_rules progression takes mode 'none' (no levelling), maxLevel (default 20; null = no cap), xpThresholds (XP for levels 1, 2, ...; the last step repeats) and profBonus (bonus by level; the last value holds). character_manage create, update and level_up refuse a level above the world's cap, naming the rule, and write nothing; the schemas no longer stop at 20. add_xp and get_progression read the world's thresholds and cap (get_progression table mode takes worldId). Skill checks, saves and spell DC and attack use the world's proficiency curve." },
    { id: '2026-09-26-15', title: 'World spells', detail: "table_rules kind spell {castingRoll?: {dice ('2d6'), modifier, ability?, target}, cost: [{pool, delta}], effects: [{type damage|healing|condition|pool, dice?, damageType?, condition?, duration?, save?: {ability, dc?}, saveEffect half|none, pool?, delta?, target target|caster}], contestedBy?: 'unbind', miscast?: {on double|fail|fumble, table}, range?, castingTime?, known}. combat_action cast_spell of a world spell's name casts it instead of the SRD spell: the casting roll is on the encounter's logged dice ('cast <name>'), costs are signed pool moves written with history (a spend the caster cannot pay is refused; a failed cast still pays), unbinderId contests a contestedBy: 'unbind' spell (the unbinder rolls the same dice; higher wins), effects land with per-target saves (dc defaults to the casting total), resistances and conditions, and the miscast table rolls on the encounter dice on a double, a failure or a fumble (every die a 1). No spell slots. known: false needs the spell in the caster's knownSpells. actionResult.worldSpell carries the roll, costs, unbind, effects and miscast." },
    { id: '2026-09-26-16', title: 'Unit break tests', detail: "A unit token's unit block takes morale, breakAt (a fraction of models, default 0.5) and routed. When an attack or volley, a spell (SRD or world) or combat_manage adjust_hp carries a unit from above breakAt to at or below it, still standing and not routed, the reply prints BREAK TEST DUE with the morale and the set_unit call; actionResult.breakTests (adjust_hp: breakTest) carries it. The engine does not roll the test. combat_manage set_unit takes routed, morale and breakAt; a routed unit's volley is refused and the unit line shows ROUTED." },
    { id: '2026-09-26-17', title: 'Clock corrections and records ahead of the clock', detail: "world_manage update {correction: true} fixes a wrong clock without time passing: no regeneration and no elapsedHours or time_passed note; the reply has correction {from, to, deltaHours}. A plain update that moves the clock 72 hours or more, or backwards, carries a hint to use correction. Records dated after the world clock (fired scheduled rows, precedents, knowledge roads, narrative section stamps; not debts) are named at session boot as a CLOCK warning, in get_context as world.clockWarning, and row by row in world_manage audit ('records dated after the world clock (advisory)'). Nothing is changed by them." },
    { id: '2026-09-26-18', title: 'Waaagh! energy', detail: "A world spell's castingRoll takes bonusFromNearby {range, per (1), max?, match: {species?, band?, tag?, nameIncludes?}, overloadAt?}: the caster's allies within range feet that match (living, same side, not routed; a unit counts its live models) add +1 per `per`, capped at max, to the casting total. The banner prints the count and bonus and actionResult.worldSpell.nearbyBonus carries {count, bonus, overload}. At overloadAt or more the spell's miscast table rolls as well (miscast.on: 'overload'), once, on the encounter's dice. A condition a miscast table puts on the caster now reaches the caster's token too. Tokens take species and tags (create, add_participant, bestiary creatures); a character's token matches on the sheet's race." },
    { id: '2026-09-26-19', title: 'Battle cries', detail: "combat_manage battle_cry {encounterId, participantId, name ('Waaagh!'), range (60), match?, rounds (1), attackAdvantage?, damageBonus?: number | dice, speedBonus?, moraleBonus?, ability?, actionCost? ('none')} buffs the caller and every matching ally within range. While it lasts their attacks roll with advantage, a hit adds the damage bonus (dice rolled on the encounter's stream and logged as '<name> damage'), speed rises, and a unit's break test adds the morale bonus. It ends at the start of the caller's turn after `rounds` rounds (the turn start says it fades). ability names one on the caller's token: it must be ready and is spent (a recharge ability rolls to return like a breath weapon). A call with no effect, or a spent or missing ability, is refused and writes nothing. The state view lists buffs and species." },
    { id: '2026-09-26-20', title: 'Mob rule', detail: "A unit's unit block (and combat_manage set_unit) takes mobRule {per, maxBonus?, attackBonusPer?, nearby?: {range, match}}. On BREAK TEST DUE the unit adds +1 morale per `per` live models (plus the live models of allied units in range, when nearby is set), capped at maxBonus, as a labelled term ('mob rule (10 models)'); a battle cry's moraleBonus joins it. Each attack or volley by the unit adds +1 to hit per attackBonusPer live models, with a note. set_unit {mobRule: null} clears it." },
    { id: '2026-09-26-21', title: 'Growth tracks', detail: "table_rules kind growth_track {pool, steps: [{at, form, note?}], perKill?, perBandAbove?, perVictory?}. An attack that drops a combatant to 0 HP adds perKill, plus perBandAbove for each band step the victim stands at or above the killer, to the killer's pool (when the killer's sheet has it), with 'kill: <victim>' in its history; the attack reply shows a GROWTH line and actionResult.growth. party_manage after_battle {victory: true} adds perVictory to each surviving member with the pool (growth[]). When any write takes the pool across a step (kills, victories, adjust_pool, offer, table writes) the reply carries growthReady {track, pool, at, form, note?, call}: the character_manage set_form call to make. It is never made for you, and a character already in that form is not offered it. Boot counts growth_track as data." },
    { id: '2026-09-26-22', title: 'The Orruk Waaagh! preset', detail: "table_rules import {worldId, preset: 'orruk-waaagh'} loads a homebrew greenskin set: the Gorkamorka favour family (gork and mork, no jealousy), teef and the WAAAGH! badge, the Orruk and Grot species, the Brute, Ardboy, Wurrgog Prophet and Weirdnob Shaman classes, the Grot-to-Warboss bands, the Orruk Ardboy, Orruk Brute, Orruk Megaboss and Great Warboss statblocks (CR 1 to 13), the Getting Bigga growth track (Brute at 10, Megaboss at 30, Great Warboss at 60), the Waaagh! Overload table, and the spells Foot of Gork (grows with the boyz nearby and can overload), Green Puke and Mighty Waaagh!. docs/table-rules/orruk-waaagh.md shows how to build Grimgor, Wurrzag and Azhag." },
    { id: '2026-09-29-01', title: 'Scheduled rows stay in their own world', detail: "A scheduled row belongs to a world by its own worldId, or, when it has none, by its character's world. process_scheduled, list_scheduled, world_manage advance (dueNow.scheduled), the boot packet and get_context all read it that way: this world's untagged rows fire and show, another campaign's never do. An untagged row whose character is untagged or gone is listed by id as unscopedOwnerUnknown and fires nowhere. schedule_change without worldId tags the row with the character's world. scope_scheduled {worldId} now stamps only untagged rows on that world's characters; scope_scheduled {worldId, scheduleIds, preview?} takes rows by id, refuses one whose character belongs to another world (naming it), and takes an untagged character's row only this way." },
    { id: '2026-09-29-02', title: 'Carry capacity by size', detail: "Carrying capacity (inventory get and get_detailed) is STR x 15 times the sheet's size: Tiny x1/2, Small and Medium x1, Large x2, Huge x4, Gargantuan x8. The size is the sheet's own (forms and species set it); unset counts as Medium. A Huge STR 24 sheet carries 1,440 lb. A carry_capacity pool still overrides it." },
    { id: '2026-09-29-03', title: 'Breaking a hold clears that hold', detail: "combat_action grapple {move: 'break', targetId: <holder>} removes every condition sourced 'grapple: <holder id or name>' from the escaper's sheet and token, whatever it is called, except Prone (escaping doesn't stand you up). A condition from any other source (a spell's Restrained, a net, another holder) is never touched; unsourced Clinched, Grappled and Restrained still clear." },
    { id: '2026-09-29-04', title: 'Damage with no actor', detail: "combat_manage apply_damage {encounterId?, targetIds, dice: number | dice ('6d10', '6d10+3d10'), source, damageType?, save?: {ability, dc, half (default true)}} deals damage nobody is attacking with: rubble, a trap, a bite rolled off-turn. It never spends an action. In an encounter the dice roll once on the fight's stream (logged as 'damage: <source>'), each target saves, resistances apply, a concentrating sheet makes its CON save (0 HP ends it), a unit carried through breakAt owes a break test (breakTests), HP writes through to the sheet and the combat log names the source. With no encounterId, targets are character ids: logged dice, saves from the sheet, HP written to the sheet; a character with a live token is taken through its encounter (routedToEncounter). lair_action and use_ability now also check concentration and break tests. Unknown targets or dice are refused and nothing is written." },
    { id: '2026-09-29-05', title: 'Multi-term free rolls', detail: "math_manage roll takes sums of dice and numbers: '6d10+3d10', '6d10+3d10+4', '2d6+1d4-1'. They roll on the same seeded dice as any other roll, the steps list each term's dice, and session_manage rolls logs every die with its own sides; passing the seed back replays the roll. Single-term syntax (4d6dl1, 2d20kh1, 1d6+2!) works as before." },
    { id: '2026-10-04-01', title: "Crypto dice by default", detail: "Every unseeded roll now draws from crypto.randomInt: encounters, quick spawns, math_manage roll/check/reroll/pool, concentration, stunts, synthesis, rests, potions, travel, theft, perception, auras and random encounters. Each is logged with a unique crypto:<nonce> key and source 'crypto'. Pass seed only for a deterministic replay (source 'seeded'). Encounter and math replies state dice: 'crypto' | 'seeded:<seed>'. session_manage rolls takes worldId, since, purpose, source and stats: true for the d20 fairness audit (count, mean, nat20/nat1, chi-squared against 30.144). Fights no longer need a dice script outside the engine." },
    { id: '2026-10-04-02', title: "Era jump", detail: "world_manage era_jump {worldId, day, time?, label, threads?: dormant|archived|keep, scheduled?: cancel|keep, resetAbilities?, dryRun?} starts a new era in one call: the clock moves by correction (no regeneration), environment.era = label, active plot threads are parked with an '[era: label]' section, the world's unfired scheduled rows are cancelled, abilities read ready and legendary pools refill, wall-clock effects expire. dryRun reports without writing. cancel_scheduled now stamps cancelled_at (hard: true deletes); list_scheduled {includeCancelled} shows them. The era label shows in boot, the status strip and clockWarning; boot warns 'CLOCK: no world day set' when clocks wait on a day the world never had." },
    { id: '2026-10-04-03', title: "XP award ledger", detail: "Every XP write leaves a row in xp_awards (who, how much, why, which tool). character_manage add_xp requires reason; combat end {xpAward} records 'encounter <id>'; stunt {xpAward} records 'stunt: <intent>'. An award narrated at the table but not yet applied goes in with award_note {characterId, amount, reason} and lands later with post_awards {characterId | worldId}; list_awards reads the ledger. While awards are pending, boot prints 'XP owed: +N (k awards)' and the status block footer shows 'xp owed +N'." },
    { id: '2026-10-04-04', title: "Reconcile the sheets", detail: "world_manage reconcile {worldId, characterId?} reads every sheet against inventory, live encounters and the precedent ledger and names each drift with the call that fixes it: equipped rows with no item behind them, duplicate attack profiles, a profile whose item (new optional field on attacks) is gone, conditions citing a superseded or missing prec- id, abilities and legendary pools still spent with no fight on, unposted XP. Read-only; boot shows 'RECONCILE: n findings' with the first five. precedent_manage supersede lists every condition, note and item still citing the old id." },
    { id: '2026-10-04-05', title: "Item API fixes", detail: "item_manage create defaults value and weight to 0 and keeps fractions; the reply's id is item.id (reference it as {{step1.item.id}}). search takes query as an alias of name and warns when called with no filter. Items carry an optional worldId (create/search/list honour it; includeUnscoped: true adds legacy rows; scope_items {worldId, itemIds | all: true} stamps them). batch_manage execute_sequence fails a step loudly on an unresolved {{ref}} with knownSteps, availableKeys and a did-you-mean hint. fields walks dotted paths of any depth and reports fieldsNotFound with availableFields instead of bare success." },
    { id: '2026-10-04-06', title: "Obligations without money", detail: "ledger_manage rows carry kind: debt (default) | oath | meeting | border | favour. Only debts have an amount; the other kinds need a consequence and ride the same due/grace clock, so an owed meeting lapses like a loan and the engine names what breaking it means. list {kind} filters; openExposure sums currency debts only, openObligations counts the rest. settle reads KEPT and default reads BROKE for them; boot's Clocks section shows them by kind word." },
    { id: '2026-10-04-07', title: "Montage roll", detail: "improvisation_manage montage {characterId, task, dc, dice?, ability?, modifier?, cleanMargin?: 5, costs?: {hardWon, costly}, hours?, worldId?, journal?} resolves a long stretch on one logged die: clean at dc + cleanMargin (free), hard_won at dc (costs.hardWon applied), costly below (costs.costly). hours moves the world clock; the line '[montage] task — tier (roll X vs DC Y) — cost: …' lands in the session log. Forty-eight cells, one roll." },
    { id: '2026-10-04-08', title: "Exposure timers", detail: "character_manage set_exposure {characterId, name, pool, perHour, cap?, thresholds?: [{at, condition: {name, effect?, duration?}, once?}]} puts a timer on a character; clear_exposure stops it. Every world_manage advance (and traverse {advanceClock}) adds perHour × elapsed hours to the pool, clamped to cap, and adds each threshold's condition once when crossed; the reply carries exposure[]. A correction never ticks. advance {fireScheduled: true} also fires the due scheduled rows in the same call. Brine-bound is set_exposure {pool: 'dry_hours', perHour: 1, cap: 12, thresholds: [{at: 12, condition: {name: 'Drying Out'}}]}." },
    { id: '2026-10-04-09', title: "Damage scales with band", detail: "The band rule takes an optional damageScale {perStepBelow: 0.5, perStepAbove: 1.25, floor: 0.25, cap: 2}. When attacker and target both carry bands, damage is multiplied by the band gap (clamped), applied after resistances and before part caps, min 1. It reaches attacks, volleys, grapple surface damage and apply_damage with the new actorId; never execute, heals, spells or actorless damage. Results carry bandScale {steps, multiplier, before, after}; attack {bandScale: false} skips it for one swing. A world without the field is unchanged." },
    { id: '2026-10-04-10', title: "Underwater fights and sheet speeds", detail: "Character sheets carry speed, swimSpeed and flySpeed (character_manage create/update; a world species rule's speeds are stored at create; set_form carries the creature's). Tokens hydrate movementSpeed from speed; the status block shows SPD 30 / swim 40. Encounters take an environment {medium: air | water | vacuum, depthFt, pressure: {startsAtFt, damagePerRound, unlessTag}, rangedAllowed, meleeDisadvantageUnlessDamageType, swimTag} on create or with combat_manage set_environment, shown on get as ⟨water · 40 ft⟩. In water, or on a terrain.water cell in an air fight: movement is swimSpeed else half speed; ranged attacks are refused unless rangedAllowed; melee is at disadvantage unless the damage type is listed (piercing) or the attacker carries the swim tag ('aquatic'); at or past the pressure depth every untagged token takes the pressure damage at the start of its turn." },
    { id: '2026-10-04-11', title: "Skaven of the Horned Rat", detail: "table_rules import {worldId, preset: 'skaven-horned-rat'} loads an Age of Sigmar rule set for a Grey Seer climbing to Verminlord: the Clanrat-to-Horned-Rat band ladder with band-scaled damage, warp-tokens, a jealous favour family (horned_rat_favour / clan_standing, warpstone_taint outside it), Skaven and Grey Seer, Verminlord forms offered by the Ascension track, the Warpstone Hunger addiction ladder, a bestiary from the Clanrat tide to the Boneripper, four tables and the Lore of Ruin with (warpstone) variants. Underneath: growth_track steps may carry a condition or a roll_table and auto: true, so a rung applies itself once on the crossing (growthApplied) instead of only offering a form, and tracks take a direction; spell costs, boosts and side effects run the growth check; combat_action cast_spell takes boost {pool, delta, modifier?, extraDice?, sideEffect?} to spend a token on a casting roll; combat_manage set_unit accepts models / hpPerModel to reinforce a unit (reinforced); agent prompts gain a knowledge slice from knowledge_manage that forbids stating anything beyond it on restricted or secret matters. Guide: docs/table-rules/skaven-horned-rat.md." },
    { id: '2026-10-04-12', title: "Ships are rows: the void-combat lane", detail: "A table_rules kind vessel {hull, ac, shields: {max, regenPerRound}, sections: [{name, hp, ac?, breakAt?, role: drive | guns | bridge | reactor | hangar | other}], weapons tied to their section, speed, band} becomes a character row with character_manage create_vessel {worldId, vessel, name?}, so hull, shields and sections persist across sessions and add_participant takes it like any character. In combat the shields pool drains before the hull on every damage path (shieldsAbsorbed, shields x/y; the row's pool follows) and refills at the start of its turn; sections bite by role: drive crippled = adrift, guns crippled = that section's weapons refused, bridge crippled = disadvantage, reactor dead = reactorBreach with a logged d6 each turn start where a 1 destroys the ship. Called strikes aim at a section with atPart. combat_manage board {encounterId, attackerId, targetId, rooms?} opens an empty boarding encounter linked by encounters.parent_id and noting the target's rooms; end {winner?, summary?} on it writes boardingResult to the void fight, and get on either side shows the link. Guide: docs/table-rules/vessels.md." },
    { id: '2026-10-11-01', title: "Action Surge and extra actions", detail: "An ability with grantsAction: true (abilities: [{name: 'Action Surge', grantsAction: true}] on the sheet or the token) banks one extra action on its user's own turn: combat_manage use_ability spends it for nothing, or combat_action attack / grapple {actionSurge: true | 'Action Surge'} spends it in the same call once the action is already used (a no-op while the action is free; the result says actionSurge.spent). The extra pays for a second Attack action (multiattack included), a second Dash (the move budget follows: 90 ft at speed 30), a Dodge, Help, Ready or a spell, and dies with the turn. The surge is marked spent on the token and mirrored to the sheet (unless it has a recharge), so the next fight starts with it spent until character_manage restore_ability or a rest. Any ability now spends its actionCost (action by default, or bonus | reaction | none); action and bonus only on the user's own turn, reaction and none off-turn too. The state view shows ⚡ extra actions N and marks ⚡ action-granting abilities and [bonus]/[free] costs." },
    { id: '2026-10-11-02', title: "Pins the way you write them", detail: "Execute and break used to recognise a hold only when its source was exactly 'grapple: <actor id>'. One matcher now reads every way a GM names the holder: the canonical source, a prefixed one ('pinned by Marine', 'held by marine'), or the bare id or name; the whole remainder must be the holder, so 'Marines' never names Marine. Pinned counts as a pin beside Restrained (or Grappled + Prone), execute reads the token first and falls back to the sheet (pinFrom says which), and the refusal lists what it found and what it needs. combat_manage add_condition {fromGrapple: <holder id or name>} writes the canonical source for you (heldBy in the reply; an ambiguous name or a conflicting condition.source is refused). A break clears a prefixed hold with its extras (not Prone); a hold sourced to the holder's bare name clears only Clinched/Grappled/Restrained/Pinned, so Frightened-of-the-holder is never touched." },
    { id: '2026-10-11-03', title: "No contest against the helpless; posted grapple results", detail: "A target that is unconscious, asleep, incapacitated, paralysed, stunned, petrified or at 0 HP is held without a roll (a house ruling; 5e RAW lets an incapacitated creature still contest), with autoWin.reason saying why; the attack is still spent, and a break against a helpless holder succeeds the same way. What is read is the token when there is one (its conditions and hp), else the sheet, so a stale sheet condition never decides a live fight. combat_action grapple takes outcome: 'win' | 'lose' for a contest the table already resolved: no d20, the attack spent, lose writes nothing; with a win, damage is the throw/slam surface damage (a number as posted, dice rolled on the fight's dice, still band-scaled). attack keeps hit|crit|miss; execute refuses lose." },
    { id: '2026-10-11-04', title: "Grapple without an encounter, and execute on the sheets", detail: "encounterId is now optional on combat_action for grapple alone (every engine action still requires it); placeholders like 'none' mean no encounter. With none, two live tokens in one fight are routed there (routedToEncounter), one side in a fight or two fights is refused, and neither in a fight runs on the character sheets with logged dice, the world's proficiency curve and expertise. execute on sheets reads the pin from the target's sheet, applies damage to the row (a number as posted, dice as a crit on an 'execute damage' roll, defences applied) and at 0 HP kills through the same path as character_manage kill: HP 0, concentration ended, a corpse row stamped with the world (writesTo 'sheet'). An execute with no damage is a coup de grâce on both paths: its HP, defences bypassed; in a fight the token still only drops to 0 HP (no corpse)." },
    { id: '2026-10-11-05', title: "One Stealth number per character", detail: "Every sheet was born with a Stealth and Perception column of 0, and since the column was authoritative that 0 displaced DEX/WIS + proficiency on every check: a level-5 rogue with DEX 16 rolled +0. The column is tri-state now. Empty means the sheet computes it (ability + proficiency, doubled by expertise, on the world's proficiency curve); any number, 0 included, is a stat-block override that replaces the computed value, set with stealthOverride/perceptionOverride at create or update and cleared with null. roll_skill_check, stunts, spatial look, POI discovery and the eavesdrop layer all roll the same number, the eavesdrop dice land in roll_log, and spawned preset creatures take their stat-block totals (a preset 0 means not listed). Existing sheets were migrated by the journal: a 0 nobody wrote became empty, a non-zero bonus nobody wrote as an override became computed + bonus, an override you set stayed; every move is a world_manage reconcile finding (skill_override_migrated) carrying the restore call until you acknowledge it with reconcile {acknowledge: ['skill_override_migrated']}." },
    { id: '2026-10-11-06', title: "apply_damage kills feed the growth track", detail: "combat_manage apply_damage with actorId now credits every target it drops from above 0 to 0 as a kill on the actor's growth track (perKill, plus perBandAbove for a victim of its band or above), in order, on the encounter path and on the sheets; a routed call credits once. The reply carries growth: [{victimId, track, pool, delta, from, to, growthReady?, growthApplied?}] and a ⬆ GROWTH line per kill, and an auto rung's condition lands on the actor's token as well as the sheet. A sheet execute credits the kill the same way. Attacks are unchanged; the credit lives in one hook (creditKill) the three paths share." },
    { id: '2026-10-11-07', title: "Surprise", detail: "combat_manage create {..., surprised: ['gob-1']} (or set_surprised {encounterId, participantIds, reason?} in round 1, before their first turn) catches creatures flat-footed: their round-1 turn passes on advance (noted, with regeneration, recharge and durations still ticking), and until it has they make no opportunity attacks or readied swings, take no reaction attack, action or legendary action. A surprised first actor's slot passes at create. The initiative line shows 😲 surprised and STATE_JSON carries surprised: true; a creature downed before its slot clears the flag there, so a heal in round 2 does not cost it another turn. An id that names nobody is refused and nothing is written; surprised: false clears a flag set by mistake." },
    { id: '2026-10-11-08', title: "Placed stats are final", detail: "character_manage create used to add the species ability bonuses to whatever stats you passed, with no note on the card, so a placed array came out bumped. Stats you pass are now taken as final; omit them for the 10 baseline plus the species bonuses (SRD or your world's species rule); pass applySpeciesAbilityBonuses: true when the scores are raw rolled or point-buy numbers and the bonuses should be added, or false to refuse them even on the baseline. The reply and the create banner say which happened in statsNote, only when the species has bonuses. npc_manage create forwards omitted stats as omitted, so an NPC made without stats gets the baseline plus bonuses and the note is honest." },
    { id: '2026-10-11-09', title: "No more Stalker by default", detail: "Characters created without a background were stored as 'Stalker', a placeholder from one table, and a world that defined a background of that name handed its skills, tools, languages and gold to everyone made without one. Omitted now means none (the reply's _rules.background is null); a background asked for by name still resolves through your world's rule and then the SRD. character_manage update {characterId, background: null} clears one. Existing rows keep whatever they have." },
    { id: '2026-10-11-10', title: "Create says what it ignored", detail: "character_manage's input schema is shared by every action, so a key create did not take (addConditions, xp, preview, removeConditions) passed the tool boundary and vanished under a success banner. create now accepts addConditions (merged into conditions by name, the same way update does) and xp (starting XP). Any other key the tool declares for another action comes back in ignoredParams with a message line naming the nearest valid key or, for update-only keys like preview and removeConditions, what to do instead; the character is still created and the banner prints the line as a warning. A key the tool declares for no action at all (a typo) is still dropped at the MCP boundary before the engine sees it. Other actions are unchanged." },
    { id: '2026-10-11-11', title: "An error reply no longer burns its opId", detail: "A call that failed validation or named an unknown action used to be stored as applied, so the corrected resend with the same opId was refused as 'already used for a different call'. The guard now reads a string error code (validation_error, invalid_action) and the MCP isError flag the same way as error: true: everything is rolled back and the opId stays free, with the first line saying 'op <id> NOT applied (error) — opId still free; fix the call and resend with the same opId'. A reply that says writes: 'none' (a preview, a refusal) commits its audit row but does not consume the opId either ('op <id>: nothing written — opId not consumed'), so session_manage op_status now reports such previews as 'did not apply'. opIds burned before this fix heal themselves: a stored error reply reads as absent, op_status says it did not apply, and the retry runs. Unknown-action replies now carry writes: 'none'; the audit log counts a validation failure behind a banner as a failure." },
    { id: '2026-10-11-12', title: "world_manage create needs only a name", detail: "The tool's outer schema said seed, width and height were optional while the action required all three, so {action: 'create', name} failed with a generic hint. Now seed is optional: omit it and the engine makes an 8-hex crypto nonce, echoed as seed with seedGenerated: true and named in the message and the banner's new Seed row, so you can record it. width and height default to 100, as session_manage initialize always did. An explicit seed is kept as given. generate still requires its seed (the world's id and name derive from it) and its description says so." },
    { id: '2026-10-11-13', title: "Summary output keeps the handles, and the op line", detail: "output_mode: 'summary' replaced every oversized value with its size, which erased item.id after item_manage create, precedentId on a search and the ids inside session_manage find — the very handles the next call needs. An oversized object now keeps its id-like keys (id, fooId, foo_id) and a name of 80 chars or less beside _keys (the number of keys it had); a list whose rows carry an id key keeps those handles per row, 25 rows a list and 50 a reply, with the remainder counted as {_more: n}; a top-level …Ids list of ids is kept up to 50. Lists and objects without a handle still read '[N items]' and '{N keys}', so condition lists are as small as before. The guard's first line ('op v1 applied', 'REPLAYED …', 'NOT applied …') now rides summary and json replies as _op instead of being dropped; json mode without a guard line is unchanged." },
    { id: '2026-10-11-14', title: "weather and location on the world, with did-you-mean", detail: "world_manage update refused {environment: {weather: 'rain'}} with zod's bare 'Unrecognized key(s)' while the tool's own docs said 'weather', and there was no place to write where the party is. The environment now has location (free text, 'Vorago docks'), and update accepts the aliases weather (→ weatherConditions), currentLocation and place (→ location), currentDay and dayNightCycle; the reply lists what it renamed as aliased. A misspelt key is refused by name with the nearest accepted key ('environment.wether is not a world environment key. Did you mean weatherConditions? Accepted: …') and writes nothing; an alias and its canonical key with different values is refused as a conflict. Where it shows: the full status block gains an AT row (the character's room, else the world location, clipped to 40 chars) and shows weather even on a world with no clock; the compact block falls back to the world location when the character has no room (showLocation: false still hides the row); boot opens with a Now line (Day 47, 06:00 · era M42 · sleet · at Vorago docks) and the packet carries weather and location; get_context world carries weather and location, the party's currentLocation still winning." },
    { id: '2026-10-11-15', title: "Spend and restore one ability on the sheet", detail: "character_manage spend_ability {characterId, name, reason?} marks one ability spent and restore_ability {characterId, name | all: true} readies one or every spent ability, without resending the whole abilities array. Spending here is bookkeeping: it grants no action (use combat_manage use_ability or attack {actionSurge} in a fight). Both patch the same ability by name on the character's live tokens in every active encounter (liveTokens; tokensWithoutAbility lists encounters whose token lacks it), so token-only abilities and recharge state are never clobbered; restore_ability all readies a recharge ability on the token too. Unknown, already-spent and already-ready abilities are refused and write nothing. world_manage reconcile's ability_spent_outside_combat hint now names restore_ability." },
    { id: '2026-10-11-16', title: "Battle Master manoeuvres on the superiority pool", detail: "The sheet takes superiorityDie ('1d6' to '1d12') and maneuverAbility ('str' | 'dex', default the higher) in its combat profile; the dice are the superiority pool (adjust_pool {pool: 'superiority', value: 4, max: 4, refresh: 'short'}). combat_action attack {maneuver: 'trip' | 'menacing' | 'disarming'} adds the die to a hit's damage (doubled on a crit, never rerolled) and the target saves STR / WIS / STR against 8 + proficiency + the modifier: a failed save means prone (not above Large), frightened of the attacker until the end of the attacker's next turn, or the held item (maneuverItem, else the first in the part's holds) falls as a prop at its feet with the sheet's parts following. maneuver: 'precision' rolls the die only on a miss it could make up, never on a natural 1, and folds it into the attack roll (maneuver.turnedHit); maneuver: 'riposte' with reaction: true answers a melee miss by the target against you this round. A missing die or pool, an empty pool, a posted outcome, a volley or a cleave are refused before any roll with writes: none; the die is spent only when it was rolled, with the reason on the pool's history, and the result carries maneuver {name, die, roll, spent, pool: {before, after}, dc?, save?, applied?}. Guide: docs/table-rules/fighter.md." },
    { id: '2026-10-11-17', title: "Fighting styles the engine applies", detail: "character_manage update {fightingStyle: 'great_weapon' | 'dueling' | 'archery' | 'defense'} lives in the combat profile and rides onto the token. archery adds +2 to hit on a ranged attack (a profile's ranged, the call's ranged, or a shot from beyond reach on the grid); great_weapon rerolls weapon dice of 1 or 2 once on a two-handed melee hit (attacks [{twoHanded: true}] or attack {twoHanded: true}), crit dice included, logged as 'damage reroll (great weapon fighting)', never an added die; dueling adds +2 damage to a one-handed melee hit (not twoHanded, not hand: 'offhand', not while a weapon is equipped in the offhand slot); defense adds +1 to the target's derived AC while it wears equipped armour, never to a dc you pass or an aimed part's own AC, so a sheet whose ac already counts it should not set defense. Opportunity and readied attacks get the same treatment; a posted outcome takes none. The result carries fightingStyle {style, applied, attackBonus?, damageBonus?, rerolls?, note} and names the target's defense. Guide: docs/table-rules/fighter.md." },
    { id: '2026-10-11-18', title: "Rests refill what you marked", detail: "A resource pool takes refresh: short | long | none (character_manage adjust_pool {pool: 'superiority', value: 4, max: 4, refresh: 'short'}): rest_manage short refills short pools, long refills short and long, and a pool already full is left alone; each refill is on the pool's history and in the reply's refilled[]. An ability takes perRest: short | long (abilities: [{name: 'Second Wind', perRest: 'short'}]): combat_manage use_ability, battle_cry and combat_action attack {actionSurge} mark it spent on the token and the sheet, the next fight starts with it spent even when the statline is resent, and a rest readies it (world_manage reconcile no longer calls that drift). A long rest also restores legendary resistances (legendaryResistancesRestored), hit dice keep their label and history, and travel_manage rest runs the same rules per party member and claims only what it wrote. The in-combat guard now reads the database: a rest while the character is a token in an active encounter row is refused with the encounter id and combat_manage end (writes: none); a completed or paused fight does not block." },
    { id: '2026-10-11-19', title: "The Day 366 principles are yours to write", detail: "The shared day-366 preset carried one table's prose: two principles named Luciel and one named Scions. The texts are generic now (the player character, healthy units); the Astartes band ladder and the Thrones lexicon stay as the preset's mechanics. Worlds that already imported it had those three lines rewritten where the stored text still matched the old preset word for word; anything you had edited was left alone. table_rules import now keeps principle rows your world already has (reply kept: n), so a rewritten principle survives a re-import; pass overwrite: true to replace them." },
    { id: '2026-10-12-01', title: "after_battle knows who fought", detail: "party_manage after_battle {partyId, victory, casualties?, recruits?, participants?: [id | name], encounterId?: id | [id]} moves loyalty, and pays victory growth, only to the members who fought. Name them in participants as character ids (a short id resolves like everywhere else) or names matched against the roster without regard to case: an unknown name or id, a character who is not a member, or a name two members share is refused (the ambiguous one names both ids) and nothing is written. Or pass the fight's encounterId, or a list when a raid ran as several fights: every member whose character id was a token in a listed encounter or one of its boarding encounters fought (tokens stay on the encounter after end, so an ended fight still counts); a missing encounter, or one no member fought in, is refused with nothing written. Both together are unioned, and casualties always count as having fought. With neither, every member counts as before, and the reply says so. The reply carries participantSource ('participants' | 'encounters' | 'all'), participants [{characterId, name}] (those who fought and survived), absent [{characterId, name, loyalty}] left untouched, encounterIds when a fight was read, and a note in the no-filter case; the message names the absentees. Two things to know with encounterId: prisoners are never tokens (includeParty leaves them out), so they neither gain nor lose loyalty for a fight they sat out; and a member taken off the board mid-fight with remove_participant reads as absent, so name them in participants for that case." },
    { id: '2026-10-12-02', title: "Equip and unequip keep a hand-set AC", detail: "inventory_manage equip/unequip used to write the gear-derived AC whenever it differed from the sheet, so an AC set by hand became 10 + DEX the moment a weapon or an apron went on. The sheet now carries acSource in combat_profile: 'manual' (set by character_manage update {ac} and by set_form) or 'derived' (set by any derived write). Equip/unequip derive the AC before and after the change and write the new value only when the sheet follows its gear (acSource 'derived', or a legacy row with no source whose stored AC equalled the pre-change derived value). Otherwise the number is kept, the row is stamped manual, and acChange reads \"AC kept at 17 (hand-set; gear gives 12: ...). Pass recomputeAc: true to take it.\" recomputeAc: true (equip and unequip, outer mirrored) takes the derived value and sets acSource 'derived' so gear drives it from then on. Reply carries ac {before, after, source, derived, parts}; a derived write stamps 'derived' so a legacy row stops being ambiguous after its first gear change. Live tokens keep their own AC either way." },
    { id: '2026-10-12-03', title: "acMatchesDerived hint and update {acSource}", detail: "When a kept hand-set AC equals what the gear now derives, the reply sets acMatchesDerived: true and says \"AC 13 is hand-set and the gear now derives 13 too; pass recomputeAc: true to let gear drive it from here\", so a sheet does not stay manual forever by accident. character_manage update {acSource: 'derived'} switches a sheet back to following its gear without touching gear (the number changes at the next equip/unequip); update {ac} marks it manual by itself, an explicit acSource beside ac wins, and the update reply says which rule now applies. set_form marks the form's stat-block AC manual and putting the form down restores the base's own acSource." },
    { id: '2026-10-12-04', title: "Outer slot enum names accessory2 and accessory3", detail: "inventory_manage's outer inputSchema slot enum lacked accessory2/accessory3 since #96 added them, so a direct equip into a second ring slot could not validate at the tool boundary. Fixed; inventory_manage is now in the mirror-audit list so the next inner param cannot drift." },
    { id: '2026-10-12-05', title: "Party upkeep: one pool, mouth-days", detail: "A warband eats. Stores are mouth-days in ONE linked character pool, never on the party: party_manage set_upkeep {partyId, linkPool: {characterId, pool}, mouthsFromPool?: [{characterId, pool}], extraMouths?, countRoles?, starvation?: {loyaltyDelta: -1, perDay: true}} links it and says who eats. Every member of a counted role eats unitModels ?? 1 a day and each mouth pool (captives) eats its current value, read live, so captures, Turnings and deaths change tomorrow's draw by themselves. It needs the world clock (pass worldId for a party that has none; it is written to the party), refuses a pool the character does not carry, starts charging from today and says so ('upkeep starts from Day 47; nothing before it is charged'; a re-run keeps the day unless startDay is passed), and prints the pool against today's mouths ('200 mouth-days at 18 mouths = 11 days') so a pool kept in old units is caught before it starves anyone: convert such a pool first with character_manage adjust_pool {characterId, pool, value: 200, max: 600, label: 'Stores (mouth-days)'} and never link one in old units. world_manage advance charges every whole day it crosses, beside the exposure timers (reply upkeep: [{partyId, name, days, storesFrom, storesTo, mouths, starvedDays, loyalty: [{characterId, name, from, to}]}]; message 'upkeep: The Host 200→146 (3d × 18)'); travel and montage time eat stores because they go through advance, and each charge lands in the pool's history. A day the stores cannot cover is a starving day: stores to 0, loyalty -1 for everyone but the leader and the mounts, every starving day (perDay: false docks once per shortfall and again only after a fed day). A correction (update {correction: true}, era_jump) charges nothing: the anchor moves with the clock (reply upkeepAnchored[]). party_manage upkeep {partyId, days} charges by hand; muster shows stores, the mouth breakdown and daysLeft, with STARVING while a shortfall runs; set_upkeep {clear: true} unlinks and leaves the pool alone. Resupply is still character_manage adjust_pool {delta, reason} on the linked pool; there is no adjust_stores. Guide: docs/table-rules/upkeep.md." },
    { id: '2026-10-13-01', title: "Grapple honours advantage", detail: "combat_action grapple takes advantage / disadvantage for the grappler's roll (two d20 keep high or low; both together cancel to one die) and advantageSources / disadvantageSources: ['Bulwark'] naming a condition on its token or sheet (name or source) or an active effect, with math_manage's matching (exact beats prefix beats any part, one hit). The lower band or smaller size still adds its own disadvantage and never stacks; the defender keeps only that. The breakdown prints 'd20(5,18 adv → 18)', situational says why ('Marine: advantage (GM; Bulwark)' or the cancel line), the reply carries rollMode {actor, defender}, advantageSources and disadvantageSources, and the roll log reads 'grapple (adv: GM, Bulwark; dis: lower band)' (plain 'grapple' when nothing applied; the sheet path logs 2d20kh1 / 2d20kl1). A source that matches nothing or two things is refused before any die is rolled or the attack spent — a grapple writes, so nothing is guessed (math_manage keeps warning and rolling). A posted outcome or a helpless target rolls no contest, so a flag there is noted as ignored. A key grapple does not use comes back in ignoredParams with the nearest valid key." },
    { id: '2026-10-13-02', title: "advantage: false is a straight roll", detail: "combat_action attack {advantage: false} with disadvantage unset (and volley the same) rolled two dice and kept the low one. An explicit false now means the same as leaving the flag out: one d20." },
    { id: '2026-10-13-03', title: "A helpless grappler spends no Action Surge", detail: "A grapple by an actor that is asleep, unconscious or otherwise helpless with actionSurge: true used to mark the ability spent (and mirror that to the sheet) before refusing under 'writes: none'. The refusal comes first now; the surge stays ready." },
    { id: '2026-10-13-04', title: "Custom items say where they equip", detail: "A misc, consumable, quest or scroll item could not be equipped at all, and nothing said how to make it so. item_manage create and update now take equipSlots: ['accessory'] (any of mainhand, offhand, armor, head, feet, accessory, accessory2, accessory3; outer schema mirrored). create writes it to properties.equipSlots beside the other properties; update merges it into the stored set without needing mergeProperties, so {itemId, equipSlots: ['head']} keeps acBonus and the rest; equipSlots: [] removes the key and the type defaults return (weapon: mainhand/offhand; armor: armor, or offhand with acBonus; anything else: not equippable). properties: {equipSlots: [...]} still works and is checked the same way however it arrives: an unknown slot is refused with its nearest slot (\"'mainhnd' is not an equipment slot — nearest is 'mainhand'\"), a non-array is refused, and a top-level list that disagrees with the properties one is refused; every refusal carries writes: 'none' and nothing is written. The reply carries equipSlots and the item card prints \"Equips in: accessory\"." },
    { id: '2026-10-13-05', title: "An equip refusal prints the fix", detail: "inventory_manage equip into a slot the item does not allow used to throw \"custom equippable items must define properties.equipSlots\" with no id, no slot and no call. The refusal is now {error: true, writes: 'none', actionType: 'equip', itemId, itemName, slot, allowedSlots, fix: {tool: 'item_manage', args: {action: 'update', itemId, equipSlots: [...]}}} and the message prints the exact call with the real id: \"Cannot equip \\\"Dosimeter\\\" in accessory: a misc item is not equippable until its properties.equipSlots says where. To allow it, run item_manage update {itemId: '<id>', equipSlots: ['accessory']} (or item_manage update {itemId: '<id>', properties: {equipSlots: ['accessory']}, mergeProperties: true}), then equip again. Slots: ... NOTHING was written.\" fix.args can be passed to item_manage as-is. A typed item tried in the wrong slot (a sword in armor) keeps its current slots and gains the tried one: equipSlots: ['mainhand', 'offhand', 'armor']. The not-owned, not-found and unresolved-choice refusals on equip carry writes: 'none' too, and the card prints NO WRITE." },
    { id: '2026-10-13-06', title: "One slot list; update {properties, mergeProperties: true} documented", detail: "The equipment slot list lived as a literal in four places in inventory_manage; it is now EQUIP_SLOTS in src/schema/inventory.ts, used by equip, unequip, both outer schemas and both descriptions, and by item_manage. item_manage's description now explains the two property-edit forms: update {properties} replaces the stored set wholesale; update {properties, mergeProperties: true} merges the passed keys in (shallow; a key set to null is deleted) and the reply's propertyMerge names the keys preserved; preview: true shows the diff and writes nothing. mergeProperties has its first tests. item_manage is in the mirror-audit list so the next inner param cannot drift, and an item_manage refusal that asserted write-freedom stamps NO WRITE on its card." },
    { id: '2026-10-13-07', title: "A key an action does not read is named, never dropped in silence", detail: "Every consolidated action now reports the keys it ignored. A call like world_manage update {id, environment, correctoin: true} still writes the environment, and the reply carries ignoredParams: ['correctoin'] with a message line \"Ignored params (not update parameters; nothing was written for them): correctoin — nearest valid key 'correction'.\" — the nearest valid key when one is close, the action's own hint when it has one (create's update-only keys), or \"no close match among update's parameters\". Banners that never print message get one ⚠️ WARNING line before their embed, fields: [...] always keeps ignoredParams, and output_mode json carries it as data. This was character_manage create's behaviour alone (play report 2 #10); it is the default for every action now, through the preprocess/refine wrappers that hid about twenty-five action schemas from the check before (every agent_manage action, world_manage update and advance, combat_manage, character_manage, spatial_manage, improvisation_manage). An action can opt out with unknownKeys: 'strip'; a passthrough schema (improvisation mechanics) keeps its keys and reports nothing. Envelope keys (sessionId, output_mode, fields, opId) never count." },
    { id: '2026-10-13-08', title: "A misspelt required key is caught at validation, with its twin named", detail: "item_manage create {nmae: 'Rope', type: 'misc'} used to fail with a bare \"Required\" on name. The validation reply now carries unknownParams: ['nmae'], the name issue reads \"Required — you sent 'nmae'; did you mean 'name'?\", and the hint ends \"Unknown keys (not create parameters): nmae — nearest valid key 'name'.\" writes: 'none' as before." },
    { id: '2026-10-13-09', title: "Typos reach the engine instead of vanishing at the door (tools/list now says additionalProperties: true)", detail: "Over MCP a key the tool's outer schema did not declare was stripped twice before any of this could see it — by the SDK's own object schema around the registered tool, then by the session wrapper's parse. Both parses are open now: every consolidated tool is registered with a passthrough schema and the session wrapper removes only sessionId (no handler reads it; the tenant is the only identity). The visible contract change for rpg-mcp-live is additive: each tool's inputSchema in tools/list now carries additionalProperties: true; the 42 tools, their parameters and their descriptions are unchanged, proved over the in-memory transport and the HTTP transport. The 14 tools without an action router (batch, comms, congregation, container, horde, hull/siege, knowledge, ledger, precedent, session, spawn, table_rules, travel, vehicle) re-parse with their own strip schema, so a stray key neither reaches their code nor breaks the call." },
    { id: '2026-10-13-10', title: "Cover: three sources, one best value, every number printed", detail: "Half cover is +2 and three-quarters +5 to AC on every attack roll (combat_action attack, volley, attack {legendaryCost} and {reaction: true}, NPC opportunity attacks during a move, readied attacks fired by trigger_readied, cast_spell spell attacks) and to DEX saves against an effect from the far side of it (apply_damage, use_ability, lair_action, cast_spell save spells). The breakdown prints the arithmetic: 'AC 12 +5 (three-quarters, boulder) = 17', 'DEX save 10 +3 +2 (half, Grot (creature)) = 15 vs DC 13'. The engine knows cover three ways, an explicit value always winning: cover on the call ('none' | 'half' | 'three-quarters' | 'total'; the prop spellings three_quarter and full are accepted; combat_manage actions take cover: {targetId: kind} or a bare kind for every target; on cast_spell a bare cover is every named target's default and coverByTarget overrides one; a creature-targeted spell refuses a total-cover target before the slot is spent, an area spell leaves it unaffected and lists it in coverSkipped); standing cover on the token from combat_manage set_cover {encounterId, participantId, level, against?: ['fg-handguns'] | {direction: 'west'}, reason?} until clear_cover, dropped for the round by attack {breaksCover: true} or a profile flagged breaksCover; and the map: a prop placed with a cover rating (combat_map place_prop {cover}) on the line of fire gives its rating, a living creature standing on it gives half, friend or foe. Cover never stacks: the single best source counts and the reply says which (cover {kind, acBonus, acBefore, acAfter, source, via: call | standing | computed}). Total cover refuses a targeted attack or spell before Help, an Action Surge, a manoeuvre die, ammo or a slot is spent, naming the source ('refused: total cover (rubble crest) from fg-crossbows: Varek cannot be targeted directly. Nothing was rolled or spent.', writes: 'none'); an area effect leaves a total-cover target unaffected with a line unless the GM passes 'none' for it. A posted outcome rolls no d20, so its cover is reported as ignored; a STR or CON save takes none and says so. Never fold cover into dc or declaredModifiers as well. The rule as played: docs/table-rules/cover.md." },
    { id: '2026-10-13-11', title: "Sharpshooter and Spell Sniper as data; the state view says who could hide", detail: "ignoreCover: 'half-and-three-quarters' | 'all' on an attack profile applies whenever that profile swings (total still refuses unless 'all'). On the sheet, character_manage create/update {ignoreCover} is a combat-profile field, stored, mirrored and riding onto the token: a bare value covers every attack, or scope it ({ranged: 'half-and-three-quarters'} is Sharpshooter, {spells: …} is Spell Sniper, melee the third lane). The reply reports what was lifted ('Varek ignores three-quarters cover (boulder)'). You cannot hide from a creature that sees you clearly: combat_manage get marks each token with canHide: [{from, reason}] and the line '🫥 can hide from Grot (three-quarters cover (rubble crest))' for standing or computed cover of three-quarters or better against that observer, a 'heavily obscured' condition, or set_environment {light: 'darkness'} (new) against an observer without darkvision (the token's senses.darkvisionFt, or a DARKVISION condition). A report, never a roll: the Stealth check stays the GM's call. The state view also prints a token's standing cover and '[broken this round]'." },
    { id: '2026-10-13-12', title: "Riders on area saves: prone on a failed rockslide save, in the same call", detail: "combat_manage apply_damage save.onFail / onSuccess (and savingThrow.onFail / onSuccess on use_ability and lair_action) take {conditions: ['prone', {name: 'Buried', source: 'rockslide', duration?}], mirrorToCharacter?}. Each condition lands on every target with that result, a same-type condition replaced rather than stacked, sourced '<effect> (failed save)' or '(saved)' unless the entry names its own; the token only by default, the sheet too with mirrorToCharacter, and always the row on the sheet path (no encounter). The reply carries conditionsApplied per target and a 'Conditions: prone, Buried' line; a target behind total cover receives nothing. Unknown names are kept as custom conditions with no mechanics (pair 'Buried' with 'restrained' for the mechanics). A condition object with a typo key is refused before any die is rolled (writes: 'none'). The nested outer save mirror carries the riders, proved over the real MCP boundary." },
    { id: '2026-10-13-13', title: "Shove: push or knock prone, by contest or STR save, as an attack or a bonus action", detail: "combat_action grapple {move: 'shove'} pushes the target 5 ft directly away (push: 10 is a labelled house extension) or knocks it prone (prone: true), never both. The Athletics contest decides unless save: {ability: 'str', dc?} is given; then the target rolls, DC 8 + proficiency + STR by default, legendary resistance honoured. The push is forced movement: one square per 5 ft, the whole footprint checked against obstacles, other tokens and the grid; it stops at the first blocked square and says why (pushed {feet, from, to, stoppedBy?}), spends no movement and provokes nothing. Unplaced tokens and the sheet path report a narrative push. bonusAction: true spends the bonus action instead of an attack, on the actor's own turn only. Every refusal lands before anything is rolled or spent (writes: 'none'). A hold the shover had on the target stays, with a note. Hammering Horns in one call: {move: 'shove', push: 10, save: {ability: 'str'}, bonusAction: true}." },
    { id: '2026-10-13-14', title: "Bonus-action attacks tied to a trigger; dash to a square in one call", detail: "An attack profile may carry bonusAction: true and requires: {dashed?, movedAtLeast?, hitThisTurn?}; attack {using: 'Goring Rush'} then spends the bonus action only (an open multiattack is untouched), on the actor's own turn, never with reaction, legendaryCost or actionSurge; the same keys work on the call itself. The engine counts movedThisTurn and movedSinceDash (Dash resets the second; a new turn resets both) and the melee hits made this turn, and refuses with the exact gap: 'Goring Rush needs a Dash this turn and 20 ft moved after it: dashed yes, moved 15 ft', nothing spent. Tokens without positions declare movedFt (reported as declared); a movedFt declared for a placed token is not used (the grid counts) and the refusal says so. dash {targetPosition} used to be accepted and ignored; it dashes and moves in the same call (result move {success, from, to, feet}), a refused move leaving the Dash spent and saying why." },
    { id: '2026-10-13-15', title: "Non-lethal blows: knocked out and stable, not dead; healing wakes them", detail: "attack {nonlethal: true} is a melee blow meant to subdue: refused with nothing spent when the attack is ranged (an explicit flag, or the grid says the target is beyond reach), a volley, a cleave or against a unit. A blow that drops the target leaves it at 0 HP, Unconscious sourced 'nonlethal: <actor>' and stable: no death saves, no kill credit, no corpse, and never a dying event (the GM chose to subdue, so the massive-damage rule does not fire). The contact block reads KNOCKED OUT — stable, the state view shows 💤 KNOCKED OUT (stable), and the sheet carries the Unconscious. Any healing above 0 (the heal action, engine healing, a posted adjust_hp) removes that Unconscious on token and sheet (woke {conditionsRemoved}); an Unconscious from another source, such as a sleep spell, is left alone. Every wake lane clears a knockout: a healing spell, the heal action, adjust_hp, a long or short rest and character_manage update {hp} all remove the knockout's Unconscious on token and sheet (woke in the reply), and the sheet sync carries a hand heal onto the live token." },
    { id: '2026-10-13-16', title: "A named character at 0 HP is dying, and the engine rolls the saves", detail: "Any participant with a pc or npc character row tracks death saves at 0 HP (combat_profile.deathSaves: false opts one out, true opts a villain or a sheetless token in; quick spawns, bestiary mooks and units still die at 0 as 💀 DEFEATED). A tracked token dropped to 0 goes Unconscious + Prone (source dying) on the token and its sheet, and the result prints [DYING ✓0 ✗0] with the stabilise call. On combat_manage advance into a dying slot the engine rolls the save on the fight's dice, logged forId the creature with purpose 'death save': 10+ a success, 9- a failure, a natural 1 two failures, a natural 20 back to 1 HP, conscious, and it takes this turn (the sheet is written, so the next sync keeps it). Three successes: 💤 STABLE, unconscious, no more saves. Three failures: ☠ DEAD; character_manage kill runs on the sheet with the cause and a corpse, and the line prints plainly. A save the table rolled through death_save before the slot is banked on the token (deathSaveTaken) and the slot consumes it with a note instead of rolling a second die; a save answering DEATH SAVE DUE is that slot's own. The token line, combat_manage get and the status block show 🩸 DYING ✓1 ✗2, then STABLE, then DEAD. Prompt mode: world_manage update {worldId, environment: {deathSaveMode: 'prompt'}} (or per character, character_manage update {characterId, deathSaveMode: 'prompt'}; the character's own mode wins) makes advance stop on the slot and print 🩸 DEATH SAVE DUE with the exact call; a second advance is refused with writes: 'none' until the save is rolled or posted. Auto is the default. Rule page: docs/table-rules/dying.md." },
    { id: '2026-10-13-17', title: "death_save takes participantId and a posted outcome; damage at 0 HP costs saves; massive damage kills", detail: "combat_manage death_save {encounterId, participantId} is the convention (characterId still works; both given and different is refused, writes none). outcome: success | failure | nat20 | nat1 (also pass/fail, 'natural 20', or the natural die 1-20 as a string or a number) posts the table's roll and rolls no d20. A natural 20 writes 1 HP to the sheet; a third failure kills through character_manage kill. The reply carries deathSave {participantId, roll | posted, successes, failures, isStabilized, isDead, regainedHp, hp, sheetHp} and killed. A hit while down is one failed save; a crit, or any melee hit within 5 ft, is two. Damage to a stable creature makes it dying again. When one blow's leftover past 0 reaches the creature's max HP it is dead at once, on the dropping blow too, with ☠ DEAD (massive damage) and the kill on the sheet. attack (actionResult.dying / killed), apply_damage, use_ability and lair_action all report it per target, and so do cast_spell (SRD and world spells), a readied attack or opportunity attack fired by a move, and trigger_readied: every road that drops a tracked token mirrors the sheet and runs the kill. A natural 20 clears a knockout's Unconscious too. A hand update {hp: 0} on a tracked sheet drops its live token at the next sync; one rule in the character store strips the dying marks from any HP write that lifts a sheet above 0 (a potion, a healing spell's write-back, the stabilised creature's 1d4-hour return) unless the call sets conditions itself. Any healing above 0 (engine heal, adjust_hp, a hand update {hp}) clears both counters and the dying Unconscious (prone stays until they stand); adjust_hp down to 0 on a tracked token puts it unconscious and prone like a real drop; a long rest clears the dying conditions from the sheet. A hand update {hp} above 0 strips the dying marks even when the same call adds, removes or edits conditions (only conditions set whole is kept as given), and the reply names what came off." },
    { id: '2026-10-13-18', title: "combat_action stabilize; outside a fight apply_damage says DYING and offers the call", detail: "combat_action stabilize {encounterId, actorId, targetId}: the healer must be within 5 ft and spends the action; a Wisdom (Medicine) check DC 10 is rolled on the fight's dice and printed ('Medicine d20=12 +5 = 17 vs DC 10 ✓'). A healer's kit in the actor's inventory (properties.healersKit: true, or a name like Healer's Kit) makes it automatic and spends one use on the item instance (useKit: false keeps it); Spare the Dying as a cantrip, known spell or ability is automatic too. Success: the target is STABLE and regains 1 HP after 1d4 hours, rolled at once and filed as a scheduled change on the world clock (adjust_hp +1, note 'stable: regains 1 HP') that world_manage advance {fireScheduled: true} fires; the reply carries recoversIn {hours, scheduleId, firesAtClock}. A failed check still spends the action. Refused before anything is spent (writes none): not adjacent, action spent, target above 0 HP, dead, or already stable. Without encounterId it runs on the character sheets. Outside a fight, apply_damage with no encounter on a pc/npc sheet dropped to 0 writes Unconscious + Prone (source dying) and prints '🩸 DYING — stabilise: combat_action stabilize {actorId: '<healer>', targetId}' (targets[].dying and a stabilize {tool, args} hint); no saves are rolled round by round out of a fight. Massive damage kills the sheet with a corpse; on a sheet already at 0 the whole blow counts against max HP, a lesser blow keeps it DYING and a Stable marker comes off (wasStable). get_status_block shows dying {status, successes, failures, label}. killed is one record on attack-shaped results and a list on spells and area effects (docs/table-rules/dying.md)." },
    { id: '2026-10-13-19', title: "Custom armour reads in any spelling; equip replies explain the AC", detail: "Armour templates are read by one reader (src/engine/armor.ts): baseAC in any spelling (baseAc, base_ac, ac, armorClass), the DEX cap from maxDexBonus or the armorCategory (heavy: no DEX; medium: cap 2; light: full). The mail shirt {baseAc: 13, maxDexBonus: 2} equips at 14 on DEX 12. item_manage create/update rewrite aliases to the canonical keys (aliased in the reply), refuse a category typo with the nearest name and a bad base with nothing written. Equip and unequip replies carry armor {item, category, baseAC, dexApplied, dexCap, stealthDisadvantage, strengthRequired, meetsStrength} and warnings: an armour-slot item with no readable base says so and prints the item_manage update that fixes it; a STR below the requirement notes the 5e speed penalty (not applied). A shield is {armorCategory: 'shield', acBonus: 2} in the offhand. Worn armour with stealthDisadvantage puts every Stealth check at disadvantage (math_manage, opposed, eavesdropping, montage), named in the breakdown. Two consequences for old sheets: a derived AC wearing medium or heavy custom armour with no maxDexBonus sees DEX capped at the next equip (correct 5e), and a row whose AC equalled the old wrong derivation now reads as hand-set with a visible hint, never a silent change." },
    { id: '2026-10-13-20', title: "Senses and natural armour on the sheet", detail: "character_manage create/update {senses: {darkvisionFt, blindsightFt, tremorsenseFt, truesightFt}}. A species rule sets them at create; an SRD species with Darkvision gets 60 ft. spatial_manage look in a DARKNESS room with darkvision returns the room as dim light (seenWith, visionNote; the hidden-exit Perception rolls at disadvantage); blindsight and truesight see unhindered; a legacy 'Darkvision' condition in any case still counts. The status block shows DV 60 on the SPD row; forms carry senses; tokens show them in get. character_manage create/update {naturalArmor: {base: 12, addDex: true, maxDex?}} is the floor worn armour must beat: unarmoured AC is the higher of 10 + DEX and base + DEX; a worn suit replaces it only when higher (the parts line says which beat which); shields and every acBonus add on top. create uses it for the default AC; update recomputes a gear-derived AC at once. Species rules carry it." },
    { id: '2026-10-13-21', title: "Conditional traits as data: Keen Smell fires on a tagged check; denial, wind and the scent passive", detail: "character_manage update {skillAdvantage: [{name: 'Keen Smell', skills: ['perception', 'survival'], when: 'scent', passiveBonus: 5, note}]} replaces the prose condition; the same shape covers Stonecunning, Keen Hearing or Sure-Footed. math_manage roll_skill_check / opposed (targetContext for the defender) and improvisation_manage montage {skill, context: ['scent']} apply advantage by themselves when a trait's when matches a tag; the breakdown reads 'ADV ← Keen Smell (scent)' and the roll log '(adv: Keen Smell (scent))'. An untagged check gets nothing and conditionalAdvantage names the tag to pass. Advantage and disadvantage cancel as normal; Survival tracking takes the same tag. context on an ability check or a save, and against on a check that is not Stealth, are reported as not applied rather than swallowed; a montage skill the engine cannot map says so instead of rolling +0. Denial is stated before the roll: scene_manage set {senseDenial: {scent: 'wind from the east carries everything away'}} or {targetId, scent: 'buried in peat-smoke'}; a tagged roll under it gets no advantage and quotes the reason (deniedAdvantage). Rolls are immutable: a denial set after a roll never touches it. Pass senseDenial or wind without narration to amend the latest scene: the amendment keeps whichever of the two it did not restate (inherited in the reply), senseDenial: [] clears, and a denial that names no sense is refused with nothing written. wind: 'from W' plus token positions in a fight places a source upwind (carries) or downwind (denied) of the sniffer; an explicit denial overrides it. get and the status block show passive Perception 11 and passive Perception (scent) 16; opposed stealth vs perception and roll_skill_check stealth {against: observerId} compare the Stealth total to the scent passive unless denied (passiveCheck, decidedBy). Page: docs/table-rules/senses-and-traits.md." },
    { id: '2026-10-13-22', title: "Knowers say what they need", detail: "knowledge_manage record: every knower is {id, how, fromId?, note?, day?} and every refusal now says so with an example, instead of a raw 'Expected object, received string'. Bare ids are accepted with one top-level road for all (knowers: ['luciel', 'vigil'], how: 'witnessed'; told takes fromId the same way); a road is never assumed. Each knower is checked before the fact is written, so a refused knower leaves no fact behind and the retry is not met with 'already exists'. Knowers list in the order you gave them; knowers given as one bare string instead of an array gets the same shape message. At the SDK boundary a wrong-typed knower is still wrapped in the SDK's validation envelope; the message inside it is ours." },
    { id: '2026-10-13-23', title: "Condition edits that miss say where the text is", detail: "character_manage update editConditions: a replace whose find sits in the condition's source (or a replaceSource whose find sits in the name) now prints the call that hits, with your own match and with, ready to paste. A case-only mismatch says find is case-sensitive and shows the casing that is there; a find in neither field lists the condition's name and source, clipped. A match that hits no name but one source names that condition. Every editConditions refusal happens before any write, even beside startingGold or worldId, and the reply carries writes: 'none'. A match found in several sources lists them all; preview: true runs the edits and refuses exactly as the write would, with the resulting list in wouldChange.conditions.to." },
];
